package com.cdac.cssip.user.controller; import com.cdac.cssip.user.dto.UserDtos.*; import com.cdac.cssip.user.service.UserFacade; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/users") @RequiredArgsConstructor public class InternalUserController{private final UserFacade f; @Value("${internal.api-key}") String key; private void check(String k){if(!key.equals(k))throw new SecurityException("Invalid internal API key");} @PostMapping public UserView create(@Valid @RequestBody CreateUser r,@RequestHeader("X-Internal-Api-Key")String k){check(k);return f.create(r);} @GetMapping("/by-cdac-id/{id}") public UserView cdac(@PathVariable String id,@RequestHeader("X-Internal-Api-Key")String k){check(k);return f.byCdac(id);} @GetMapping("/{id}") public UserView id(@PathVariable Long id,@RequestHeader("X-Internal-Api-Key")String k){check(k);return f.byId(id);} @PutMapping("/{id}/status") public UserView status(@PathVariable Long id,@Valid @RequestBody StatusUpdate r,@RequestHeader("X-Internal-Api-Key")String k){check(k);return f.status(id,r.status());} @GetMapping("/branches/{id}") public BranchView branch(@PathVariable Long id,@RequestHeader("X-Internal-Api-Key")String k){check(k);return f.branch(id);}}
